{
  "name": "all_pairs_gap_linear_no_adv",
  "intuition": "Simplify to basic all pairs preferences using objective gaps without requiring the unavailable 'advantage' feature, preserving pairwise ordering based on objective comparison and weighting pairs linearly by objective gap magnitude.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "none"
  },
  "operators_used": [
    "all_pairs",
    "sub",
    "abs"
  ],
  "implementation_hint": {
    "expects": [
      "objective"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # create mask for all pairs with strictly better objective\n    mask = objective[:, :, None] < objective[:, None, :]\n    batch_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # compute margin based on objective difference\n    obj_w = objective[batch_idx, winner_idx]\n    obj_l = objective[batch_idx, loser_idx]\n    gap = obj_l - obj_w  # positive gap\n    # use linear gap weighting\n    weight = gap\n    # return PrefBatch with pair indices and weights\n    return PrefBatch(mode='pairwise', pair_idx=(batch_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_linear_no_adv'})"
}
