    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # mask pairs where objective_winner > objective_loser (lower is better)\n    mask = objective[:, :, None] > objective[:, None, :]\n    batch_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    obj_w = objective[batch_idx, winner_idx]\n    obj_l = objective[batch_idx, loser_idx]\n    gap = obj_l - obj_w\n    # Ensure weight is nonnegative by clamping at zero (should be >=0 anyway)\n    weight = gap.clamp(min=0)\n    return PrefBatch(mode='pairwise', pair_idx=(batch_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_linear_nonneg_weight'})"
