{
  "name": "builder_all_pairs_tiezone_001",
  "intuition": "Inject tie-zone constraint to filter pairs with small objective difference",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "uniform_none",
    "constraint_family": "tie_zone_filter"
  },
  "operators_used": ["all_pairs", "abs", "sub", "ge", "logical_and"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    tie_zone_threshold = 1e-3\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, w_idx, l_idx = mask.nonzero(as_tuple=True)\n    obj_w = objective[b_idx, w_idx]\n    obj_l = objective[b_idx, l_idx]\n    diff = obj_l - obj_w\n    valid = diff >= tie_zone_threshold\n    b_idx = b_idx[valid]\n    w_idx = w_idx[valid]\n    l_idx = l_idx[valid]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'all_pairs_tie_zone'})\n"
}

