{
  "name": "gap_rankblend_topk_simple",
  "intuition": "Compute pairwise gap weights as inverse rank and select top-k pairs by weight to prioritize strongest pairs without imports.",
  "hyperparams": {
    "geometry_family": "sampled_pairs",
    "cap_family": "topk_cap",
    "weight_family": "gap_rank_blend",
    "constraint_family": "budget_clamp"
  },
  "operators_used": [
    "sampled_pairs",
    "topk",
    "sort",
    "nonzero"
  ],
  "implementation_hint": {
    "expects": [
      "objective"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache[\"objective\"]\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > 0\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap_scores = gap[b_idx, winner_idx, loser_idx]\n    sorted_indices = gap_scores.argsort(descending=True)\n    ranks = torch.empty_like(sorted_indices)\n    ranks[sorted_indices] = torch.arange(len(gap_scores), device=gap_scores.device) + 1\n    weights = 1.0 / ranks\n    max_pairs = int(extra.get(\"max_pairs\", 16))\n    if b_idx.numel() > max_pairs:\n        topk_values, topk_idx = torch.topk(weights, k=max_pairs, largest=True, sorted=False)\n        b_idx = b_idx[topk_idx]\n        winner_idx = winner_idx[topk_idx]\n        loser_idx = loser_idx[topk_idx]\n        weights = weights[topk_idx]\n    return PrefBatch(mode=\"pairwise\", pair_idx=(b_idx, winner_idx, loser_idx), weight=weights, meta={\"builder\": \"gap_rankblend_topk_simple\", \"max_pairs\": max_pairs})"
}
