{
  "name": "all_pairs_gap_linear_builder",
  "intuition": "Simplify to basic all-pairs builder using linear gap weights on advantage differences, removing imports and nonlinear transformations to ensure stability and pass static validation while preserving intent to weight pairs by advantage gap.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "none"
  },
  "operators_used": [
    "all_pairs"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "advantage"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    advantage = feature_cache['advantage']\n    # Identify pairs where objective of winner < loser\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Compute weight as linear gap in advantage\n    adv_winner = advantage[b_idx, winner_idx]\n    adv_loser = advantage[b_idx, loser_idx]\n    weight = adv_winner - adv_loser\n    # Ensure pair_idx tensors are int64 and 1D\n    return PrefBatch(\n        mode='pairwise',\n        pair_idx=(b_idx.to(dtype=torch.int64), winner_idx.to(dtype=torch.int64), loser_idx.to(dtype=torch.int64)),\n        weight=weight,\n        meta={'builder':'all_pairs_gap_linear'}\n    )"
}
```

