{
  "name": "rank_adjacent_pairs",
  "intuition": "Select pairs where winner rank is exactly one better than loser rank, ensuring pairs near decision boundaries without sparse band filtering.",
  "hyperparams": {
    "geometry_family": "rank_adjacent_pairs",
    "cap_family": "no_cap",
    "weight_family": "gap_linear",
    "constraint_family": "none"
  },
  "operators_used": [
    "sub",
    "eq",
    "nonzero"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "rank"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    rank = feature_cache['rank']\n    bsz, n = objective.shape\n    rank_w = rank.unsqueeze(2)  # [batch, n, 1]\n    rank_l = rank.unsqueeze(1)  # [batch, 1, n]\n    is_adjacent = (rank_l - rank_w) == 1  # winner rank exactly one better than loser\n    gap = objective.unsqueeze(2) - objective.unsqueeze(1)  # w - l\n    valid_mask = (gap > 0) & is_adjacent\n    b_idx, w_idx, l_idx = valid_mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx.to(dtype=torch.int64), w_idx.to(dtype=torch.int64), l_idx.to(dtype=torch.int64)), weight=None, meta={'builder': 'rank_adjacent_pairs'})"
}
