{
  "name": "builder_all_pairs_budget_clamp_uniform",
  "intuition": "Use all winning pairs with budget clamping by simple top-k truncation per batch without imports or loops, ensuring stable capped pair count and uniform weighting.",
  "hyperparams": {
    "geometry_family": "all_pairs",
    "cap_family": "topk_global",
    "weight_family": "uniform_none",
    "constraint_family": "budget_clamp"
  },
  "operators_used": [
    "all_pairs",
    "topk"
  ],
  "implementation_hint": {
    "expects": [
      "objective"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    device = objective.device\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > 0.0\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    max_pairs = extra.get('max_pairs', 123)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_budget_clamp_uniform'})\n    # Create a flat global ranking by batch index, winner_idx, loser_idx triplet indices\n    # to select top max_pairs pairs preserving intent.\n    rank_scores = b_idx.to(torch.int64) * 1000000 + winner_idx.to(torch.int64) * 1000 + loser_idx.to(torch.int64)\n    _, topk_indices = torch.topk(rank_scores, k=min(max_pairs, b_idx.size(0)), largest=False)\n    b_idx = b_idx[topk_indices]\n    winner_idx = winner_idx[topk_indices]\n    loser_idx = loser_idx[topk_indices]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_budget_clamp_uniform', 'max_pairs': max_pairs})\n"
}
