{
  "name": "pairwise_weighted_advantage_exp_margin",
  "intuition": "Combine advantage-based weighting with an exponential margin normalization to introduce nonlinear adaptive scaling, improving stability and diversity while maintaining pairwise preference robustness. This approach replaces linear normalization with an exponential function applied to the mean advantage, which enhances sensitivity to advantage magnitude variations, offering a structurally novel weighting scheme.",
  "hyperparams": {
    "geometry_family": "rank_adjacent_pairs",
    "cap_family": "none",
    "weight_family": "advantage_exponential",
    "constraint_family": "none"
  },
  "operators_used": ["logsigmoid", "clamp", "norm", "mean", "maximum", "neg", "mul", "sub", "div", "abs", "exp", "sum"],
  "implementation_hint": {
    "expects": ["log_prob", "advantage"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    lpw = feature_cache['log_prob']\n    lpl = feature_cache['log_prob']\n    advantage = feature_cache['advantage']\n    epsilon = 1e-6\n    mean_adv = ops.mean(advantage)\n    margin = ops.sub(ops.exp(ops.clamp(ops.abs(mean_adv), 0.0, 1.0)), 1.0)\n    norm_adv = ops.maximum(ops.mean(ops.norm(advantage)), epsilon)\n    x_raw = ops.div(ops.sub(lpw, lpl), norm_adv)\n    x = ops.mul(margin, x_raw)\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = ops.neg(ops.logsigmoid(x))\n    loss_weighted = ops.mul(loss, feature_cache['weight'])\n    loss_mean = ops.div(ops.sum(loss_weighted), ops.maximum(ops.sum(feature_cache['weight']), epsilon))\n    return loss_mean"
}

