{
  "name": "rank_adjacent_regret_gap_pairs_margin_sigmoid_weight",
  "intuition": "Builds adjacent pairs by winner rank exactly one lower than loser; weights pairs by a sigmoid margin of the regret gap to emphasize more confident preferences, leveraging regret signals instead of objective for fresh weighting and novelty.",
  "hyperparams": {
    "geometry_family": "rank_adjacent_pairs",
    "cap_family": "no_cap",
    "weight_family": "margin_regret_blend",
    "constraint_family": "none"
  },
  "operators_used": [
