    "eq",
    "to",
    "sigmoid",
    "unsqueeze"
  ],
  "implementation_hint": {
    "expects": [
      "regret",
      "rank"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    regret = feature_cache['regret']\n    rank = feature_cache['rank']\n    # winner rank exactly one better (lower) than loser\n    rank_w = rank.unsqueeze(2)\n    rank_l = rank.unsqueeze(1)\n    is_adjacent = (rank_l - rank_w) == 1\n    # compute regret gap (w - l); positive means w worse\n    regret_gap = regret.unsqueeze(2) - regret.unsqueeze(1)\n    # weight pairs with sigmoid of negative regret gap to emphasize confident winners\n    weight = torch.sigmoid(-regret_gap)\n    valid_mask = is_adjacent\n    b_idx, w_idx, l_idx = valid_mask.nonzero(as_tuple=True)\n    # restrict weight tensor to valid pairs\n    weight_selected = weight[b_idx, w_idx, l_idx]\n    return PrefBatch(\n        mode='pairwise',\n        pair_idx=(b_idx.to(torch.int64), w_idx.to(torch.int64), l_idx.to(torch.int64)),\n        weight=weight_selected,\n        meta={'builder': 'rank_adjacent_regret_gap_pairs_margin_sigmoid_weight'}\n    )"
}

