  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    bsz, n = objective.shape\n    gap = objective.unsqueeze(2) - objective.unsqueeze(1)  # w - l\n    # valid pairs: winner objective better (lower) than loser\n    valid_mask = gap < 0\n    # Compute absolute gap and clamp to reduce noise\n    clamped_gap = gap.clamp(min=-0.1, max=-1e-5)  # clamp negative gaps to [-0.1, -1e-5]\n    clamped_gap = clamped_gap * valid_mask.float()\n    # For each winner, select top-k largest negative gaps (closest losses)\n    k = min(64, n-1) if n>1 else 0\n    if k == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(torch.empty(0, dtype=torch.int64), torch.empty(0, dtype=torch.int64), torch.empty(0, dtype=torch.int64)), weight=None, meta={'builder': 'all_pairs_topk_clamped_gap'})\n    # We sort loser dim to pick top-k per winner\n    topk_vals, topk_inds = clamped_gap.topk(k, dim=1, largest=False)  # largest=False because gaps are negative\n    # Build mask for selected pairs\n    selection_mask = torch.zeros_like(valid_mask, dtype=torch.bool)\n    batch_idx = torch.arange(bsz, device=objective.device)[:, None]\n    winner_idx = torch.arange(n, device=objective.device)[None, :]\n    # scatter True at positions topk_inds along loser dim per winner\n    for bi in range(bsz):\n        selection_mask[bi, winner_idx, topk_inds[bi]] = True\n    # Extract indices where selection_mask is True\n    b_idx, w_idx, l_idx = selection_mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'all_pairs_topk_clamped_gap'})"
