  "intuition": "Focus on selecting pairs where the winner is exactly one rank better than the loser, with strictly better (lower) objectives, ensuring stable and meaningful adjacent preference signals without complex weighting schemes, thus maintaining simplicity and robustness.",
  "hyperparams": {
    "geometry_family": "rank_adjacent_pairs",
    "cap_family": "no_cap",
    "weight_family": "none",
    "constraint_family": "none"
  },
  "operators_used": ["sub", "eq", "gt", "nonzero", "to"],
  "implementation_hint": {
    "expects": ["objective", "rank"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    rank = feature_cache['rank']\n    rank_w = rank.unsqueeze(2)\n    rank_l = rank.unsqueeze(1)\n    is_adjacent = (rank_l - rank_w) == 1\n    gap = objective.unsqueeze(2) - objective.unsqueeze(1)\n    valid_mask = (gap < 0) & is_adjacent\n    b_idx, w_idx, l_idx = valid_mask.nonzero(as_tuple=True)\n    return PrefBatch(\n        mode='pairwise',\n        pair_idx=(b_idx, w_idx, l_idx),\n        weight=None,\n        meta={'builder': 'adjacent_rank_objective_pairs'}\n    )"
