{
  "name": "adjacent_rank_pairs_advantage_weighted",
  "intuition": "Select pairs with winner exactly one rank better than loser and weight pairs by gap in advantage signal to emphasize meaningful adjacent rank preferences with advantage-based weighting.",
  "hyperparams": {
    "geometry_family": "rank_adjacent_pairs",
    "cap_family": "no_cap",
    "weight_family": "gap_advantage",
    "constraint_family": "none"
  },
  "operators_used": [
    "sub",
    "eq",
    "nonzero",
    "unsqueeze",
    "mul"
  ],
  "implementation_hint": {
    "expects": [
      "rank",
      "advantage"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    rank = feature_cache['rank']  # [batch, n]\n    advantage = feature_cache['advantage']  # [batch, n]\n    # winner rank exactly one better (lower) than loser\n    rank_w = rank.unsqueeze(2)  # [batch, n, 1]\n    rank_l = rank.unsqueeze(1)  # [batch, 1, n]\n    is_adjacent = (rank_l - rank_w) == 1  # [batch, n, n]\n    b_idx, w_idx, l_idx = is_adjacent.nonzero(as_tuple=True)\n    # Compute advantage gap weight: advantage_w - advantage_l\n    advantage_w = advantage[b_idx, w_idx]\n    advantage_l = advantage[b_idx, l_idx]\n    weight = (advantage_w - advantage_l).clamp(min=0)\n    return PrefBatch(\n        mode='pairwise',\n        pair_idx=(b_idx.to(dtype=torch.int64), w_idx.to(dtype=torch.int64), l_idx.to(dtype=torch.int64)),\n        weight=weight,\n        meta={'builder': 'adjacent_rank_pairs_advantage_weighted'}\n    )"
}

